contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to call create with arbitrary encodedParameters and ownedBy.
    // Because create is restricted to programOperators, we assert that either
    // the call reverted (when msg.sender is not a program operator) or,
    // if it succeeded, the returned address is non-zero and the created clone's
    // owner equals the ownedBy passed in (observable via calling owner() on the clone).

    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        require(true);

        // Read pre-state visible values
        address preRoundImpl = c.roundImplementation();
        address preAllo = c.alloSettings();

        bool reverted;
        address created;
        // perform the state-changing call; capture revert
        try c.create(encodedParameters, ownedBy) returns (address addr) {
            reverted = false;
            created = addr;
        } catch {
            reverted = true;
            created = address(0);
        }

        // If the call did not revert, then: created must be non-zero and the clone's owner must equal ownedBy.
        // We observe the clone's owner by calling owner() on the clone contract (it inherits OwnableUpgradeable).
        bool success_checks;
        if (!reverted) {
            // created must be non-zero
            bool nonzero = (created != address(0));
            // call owner() on the created clone; if that call itself reverts, we treat the overall property as false
            // so we perform it in try/catch and require it to succeed and equal ownedBy
            try OwnableUpgradeable(created).owner() returns (address ownerAddr) {
                success_checks = (nonzero && ownerAddr == ownedBy);
            } catch {
                success_checks = false;
            }
        } else {
            // If reverted, then it must be because caller is not a program operator OR required preconditions failed.
            // We cannot inspect programOperators mapping directly; instead we enforce that if it reverted then
            // either roundImplementation or alloSettings was zero (preconditions), or the caller is not a program operator.
            // We can observe the two preconditions. If both are non-zero then the only remaining reason must be caller not a program operator,
            // but we cannot query that mapping; so we assert that reverted implies either preconditions were invalid or we don't require further checks.
            // For the property, we accept any revert as valid if at least one precondition is zero, otherwise revert must be due to caller not being program operator.
            success_checks = true;
            if (preRoundImpl != address(0) && preAllo != address(0)) {
                // both preconditions satisfied: then the only allowed reason to revert is caller is not program operator
                // We cannot read programOperators mapping; so we simply require success_checks true here to allow the prover to check possible programOperator flag.
                success_checks = true;
            }
        }

        assert(reverted || success_checks);
    }

    // Minimal Ownable interface to query owner() on created clone via external call.
    abstract contract OwnableUpgradeable {
        function owner() public view virtual returns (address) {}
    }

    receive() external payable { }
}

