contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // We take arbitrary encodedParameters and ownedBy as inputs.
    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        require(true);

        bool reverted;
        address created;
        // Attempt to call create and capture whether it reverted and the returned address
        try c.create(encodedParameters, ownedBy) returns (address addr) {
            reverted = false;
            created = addr;
        } catch {
            reverted = true;
            created = address(0);
        }

        // If create succeeded then created must be non-zero and the clone's owner() must equal ownedBy.
        // We perform an external call to owner() on the created address only when not reverted and created != address(0).
        bool ownerMatches = false;
        if (!reverted && created != address(0)) {
            // Call owner() using a low-level staticcall to avoid needing an interface declaration.
            (bool ok, bytes memory ret) = created.staticcall(abi.encodeWithSignature("owner()"));
            // ok must be true and returned data must decode to an address equal to ownedBy
            if (ok && ret.length >= 32) {
                address ownerAddr = abi.decode(ret, (address));
                ownerMatches = (ownerAddr == ownedBy);
            } else {
                ownerMatches = false;
            }
        }

        // Final property: either create reverted, or (created != 0 && ownerMatches)
        assert(reverted || (created != address(0) && ownerMatches));
    }

    // Allow receiving Ether if needed by potential implementations
    receive() external payable { }
}

