contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take parameters to exercise different caller, implementation, settings, and encoded params.
    // - callerIsProgramOperator: if true, msg.sender (this contract) will be made program operator by calling into c's programOperators mapping via low-level mechanism: because programOperators is public, there is an auto getter but no setter; however factory owner can set programOperators by direct storage only inside c which we cannot. So instead we rely on the fact that the deploying test contract is the owner in initialization flow described: the checker deploys a fresh C and then deploys this test with C passed in, so we must not assume ownership. To make a meaningful general rule we avoid trying to change programOperators and instead check that when prerequisites are missing create reverts and when prerequisites set by owner functions succeed.
    // We'll: (1) call c.updateRoundImplementation and c.updateAlloSettings as the owner — this contract is the deployer of c per spec, so these calls should succeed; (2) set programOperators mapping by directly calling transferOwnership/other means isn't available; but we can rely on the fact that the onlyProgramOperator modifier checks programOperators[msg.sender], so to allow create we set programOperators[this] via low-level call is impossible. Instead we'll assert the invariant: create either reverts or returns nonzero and when it returns nonzero then roundImplementation and alloSettings were nonzero before call.

    function run(bytes calldata encodedParameters, address ownedBy, address newRoundImplementation, address newAlloSettings) public payable {
        require(true);

        // Read pre-state
        address beforeImpl = c.roundImplementation();
        address beforeAllo = c.alloSettings();

        // Attempt to set roundImplementation and alloSettings via owner-only functions.
        // These calls will succeed only if this contract is owner. They are state-changing top-level calls.
        // We call them unguarded; if they revert, we catch below.
        bool setImplReverted;
        bool setAlloReverted;
        try c.updateRoundImplementation(payable(newRoundImplementation)) {
            setImplReverted = false;
        } catch {
            setImplReverted = true;
        }
        try c.updateAlloSettings(newAlloSettings) {
            setAlloReverted = false;
        } catch {
            setAlloReverted = true;
        }

        // Now attempt to call create. It may revert (if programOperators[msg.sender] is false or other preconditions), or return an address.
        bool createReverted;
        address created;
        try c.create(encodedParameters, ownedBy) {
            // if returns, but solidity ABI of external create returns address, need to capture; use low-level call to capture return value instead
            // However try/catch with external call returning address requires assignment; to keep single-call pattern, use alternative: perform low-level call
            // But constraint: all state-changing calls must be top-level; already used try above. We'll instead perform a low-level call to c.create to capture success and returned address.
        } catch {
            createReverted = true;
            created = address(0);
        }

        // Because try above couldn't capture the returned address via that form (we used empty try), we redo using low-level call (still top-level and state-changing). We must ensure we don't call create twice; but the earlier try either reverted (caught) or returned; in returned case we didn't record result. To avoid double state change, detect if previous create was attempted by checking createReverted flag; if not set we need to call low-level only when we know previous try didn't happen. To simplify and obey constraints, we instead perform low-level call always and consider its result as authoritative.
        // For safety, perform the low-level call now and treat it as the single create invocation used for the assertion.
        bytes memory data = abi.encodeWithSelector(c.create.selector, encodedParameters, ownedBy);
        (bool ok, bytes memory ret) = address(c).call{value: 0}(data);
        if (ok) {
            createReverted = false;
            if (ret.length >= 32) {
                created = abi.decode(ret, (address));
            } else {
                created = address(0);
            }
        } else {
            createReverted = true;
            created = address(0);
        }

        // Read post-state
        address afterImpl = c.roundImplementation();
        address afterAllo = c.alloSettings();

        // General rule (single assert): If create returned (did not revert) then the returned address is nonzero AND roundImplementation and alloSettings were nonzero at the moment of the call (we approximate by checking that after-values are nonzero — if owner updates succeeded they are reflected). Also creation never returns address(0).
        // Formally: createReverted == true OR (created != address(0) && afterImpl != address(0) && afterAllo != address(0))
        assert(createReverted || (created != address(0) && afterImpl != address(0) && afterAllo != address(0)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function. It attempts to set implementation and settings (may revert if not owner),
    // then calls create and asserts that either create reverted or it returned a nonzero address and the factory has nonzero implementation and alloSettings.
    function run(bytes calldata encodedParameters, address ownedBy, address newRoundImplementation, address newAlloSettings) public payable {
        require(true);

        // Read pre-state
        address beforeImpl = c.roundImplementation();
        address beforeAllo = c.alloSettings();

        // Attempts to update roundImplementation and alloSettings. Each is a top-level state-changing call and may revert.
        bool implUpdated;
        bool alloUpdated;
        implUpdated = false;
        alloUpdated = false;
        // try-catch on external calls allowed; the state-changing call is top-level (try c.f(...))
        try c.updateRoundImplementation(payable(newRoundImplementation)) {
            implUpdated = true;
        } catch {
            implUpdated = false;
        }
        try c.updateAlloSettings(newAlloSettings) {
            alloUpdated = true;
        } catch {
            alloUpdated = false;
        }

        // Now attempt to call create; capture whether it reverted and the returned address.
        bool createReverted = false;
        address created = address(0);
        try c.create(encodedParameters, ownedBy) returns (address addr) {
            createReverted = false;
            created = addr;
        } catch {
            createReverted = true;
            created = address(0);
        }

        // Read post-state via public getters
        address afterImpl = c.roundImplementation();
        address afterAllo = c.alloSettings();

        // Single assert: either create reverted, or it returned a nonzero address and the factory has nonzero impl and allo after our update attempts.
        assert(createReverted || (created != address(0) && afterImpl != address(0) && afterAllo != address(0)));
    }

    receive() external payable {}
}

