contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to try to make the caller be or not be a program operator.
    // The test will try to call create and record whether it reverted and whether it returned a nonzero address.
    // The invariant: if create returned a nonzero address (i.e., succeeded), then the factory's programOperators mapping
    // for this contract's address must be true (meaning msg.sender was a program operator). Conversely, if the mapping
    // for this contract's address is false then create must have reverted (i.e., not returned a nonzero address).
    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        require(true);

        // Attempt to call create; capture revert flag and returned address.
        bool createReverted = false;
        address created = address(0);
        try c.create(encodedParameters, ownedBy) returns (address addr) {
            createReverted = false;
            created = addr;
        } catch {
            createReverted = true;
            created = address(0);
        }

        // Observe whether this InvMutTest contract is recorded as a program operator in c.
        // The mapping programOperators is public, so an auto-generated getter exists.
        bool isOperator = c.programOperators(address(this));

        // General rule: create succeeded (did not revert and returned nonzero address) only if isOperator is true.
        // Equivalently: if not isOperator then create must have reverted (i.e., cannot succeed).
        assert(!(created != address(0)) || isOperator);
    }

    receive() external payable {}
}
